// MNIST inference CLI: ./cli_tool weights.json image.png -> prints predicted digit
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>

#include "lodepng.h"
extern "C" {
#include "cJSON.h"
}

static std::string readFile(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::string s;
    s.resize((size_t)n);
    if (n > 0 && fread(&s[0], 1, (size_t)n, f) != (size_t)n) { fclose(f); fprintf(stderr, "read error\n"); exit(1); }
    fclose(f);
    return s;
}

static void flatten(const cJSON* node, std::vector<double>& out) {
    if (cJSON_IsArray(node)) {
        const cJSON* c = NULL;
        cJSON_ArrayForEach(c, node) flatten(c, out);
    } else if (cJSON_IsNumber(node)) {
        out.push_back(node->valuedouble);
    }
}

struct Layer { std::vector<double> w, b; size_t in, out; };

static Layer getLayer(const cJSON* root, const char* wname, const char* bname) {
    const cJSON* w = cJSON_GetObjectItemCaseSensitive(root, wname);
    const cJSON* b = cJSON_GetObjectItemCaseSensitive(root, bname);
    if (!w || !b) { fprintf(stderr, "missing %s/%s in weights\n", wname, bname); exit(1); }
    Layer L;
    flatten(w, L.w);
    flatten(b, L.b);
    L.out = L.b.size();
    if (L.out == 0 || L.w.size() % L.out != 0) { fprintf(stderr, "bad layer shape %s\n", wname); exit(1); }
    L.in = L.w.size() / L.out;   // weight is [out, in] (PyTorch nn.Linear)
    return L;
}

static std::vector<double> forward(const Layer& L, const std::vector<double>& x, bool relu) {
    std::vector<double> y(L.out);
    for (size_t o = 0; o < L.out; ++o) {
        double s = L.b[o];
        const double* wr = &L.w[o * L.in];
        for (size_t i = 0; i < L.in && i < x.size(); ++i) s += wr[i] * x[i];
        y[o] = (relu && s < 0.0) ? 0.0 : s;
    }
    return y;
}

int main(int argc, char** argv) {
    if (argc < 3) { fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]); return 1; }

    std::string js = readFile(argv[1]);
    cJSON* root = cJSON_Parse(js.c_str());
    if (!root) { fprintf(stderr, "invalid json\n"); return 1; }

    double mean = 0.5, std_ = 0.5;
    const cJSON* meta = cJSON_GetObjectItemCaseSensitive(root, "meta");
    if (meta) {
        const cJSON* m = cJSON_GetObjectItemCaseSensitive(meta, "mean");
        const cJSON* s = cJSON_GetObjectItemCaseSensitive(meta, "std");
        if (cJSON_IsNumber(m)) mean = m->valuedouble;
        if (cJSON_IsNumber(s) && s->valuedouble != 0.0) std_ = s->valuedouble;
    }

    Layer l1 = getLayer(root, "input_layer.weight", "input_layer.bias");
    Layer l2 = getLayer(root, "hidden_layer.weight", "hidden_layer.bias");
    Layer l3 = getLayer(root, "output_layer.weight", "output_layer.bias");

    // decode png as 8-bit grayscale
    std::vector<unsigned char> img;
    unsigned W = 0, H = 0;
    unsigned err = lodepng::decode(img, W, H, argv[2], LCT_GREY, 8);
    if (err) { fprintf(stderr, "png decode error %u: %s\n", err, lodepng_error_text(err)); cJSON_Delete(root); return 1; }

    // target side length from the model input dim (784 -> 28)
    unsigned side = (unsigned)(sqrt((double)l1.in) + 0.5);
    if (side == 0) side = 28;

    std::vector<double> x(l1.in, 0.0);
    for (unsigned r = 0; r < side; ++r) {
        for (unsigned c = 0; c < side; ++c) {
            unsigned sr = (H == side) ? r : (unsigned)((double)r * H / side);
            unsigned sc = (W == side) ? c : (unsigned)((double)c * W / side);
            if (sr >= H) sr = H ? H - 1 : 0;
            if (sc >= W) sc = W ? W - 1 : 0;
            double v = img[(size_t)sr * W + sc] / 255.0;
            x[(size_t)r * side + c] = (v - mean) / std_;
        }
    }

    std::vector<double> h = forward(l1, x, true);
    h = forward(l2, h, true);
    std::vector<double> o = forward(l3, h, false);

    size_t best = 0;
    for (size_t i = 1; i < o.size(); ++i) if (o[i] > o[best]) best = i;

    printf("%zu\n", best);
    cJSON_Delete(root);
    return 0;
}
